code.cpp:
class Solution {
public:
    vector<int> smallestSubarrays(vector<int>& nums) {
        int n = nums.size();
        vector<int> answer(n);
        vector<int> nearest(31, -1);
        for (int i = n - 1; i >= 0; i--) {
            for (int b = 0; b < 31; b++) {
                if (nums[i] & (1 << b)) {
                    nearest[b] = i;
                }
            }
            int best = 1;
            for (int b = 0; b < 31; b++) {
                if (nearest[b] != -1) {
                    best = max(best, nearest[b] - i + 1);
                }
            }
            answer[i] = best;
        }
        return answer;
    }
};
